-- Create the trigger function for premature resolution block check
CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS TRIGGER AS $$
DECLARE
    iii_score NUMERIC;
BEGIN
    -- Only check when resstat is being updated to 'Resolved'
    IF NEW.resstat = 'Resolved' AND (OLD.resstat IS DISTINCT FROM NEW.resstat) THEN
        -- Calculate the Investigation Intensity Index (III) score
        SELECT 0.6 * ic.behansc + 0.4 * ic.netansc
        INTO iii_score
        FROM compliancecase cc
        JOIN investigationdetails ic ON cc.compreg = ic.compref
        WHERE cc.compreg = NEW.compref2;

        -- Block resolution if III score is above 75.0
        IF iii_score > 75.0 THEN
            RAISE EXCEPTION 'Resolution blocked: Investigation Intensity Index (III) score %.0 is above the threshold of 75.0', iii_score;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

